input.command:
python3 - <<'EOF'
import json,subprocess,re
d=json.load(open('scratchpad/session_2026-11-13-edmonton-checklist-pass/sweep/adj/findings-D-bpc.json'))
fl={(x['file'],x['line']) for x in d}
out=subprocess.run(['git','grep','-n','-i','-E',r'\b(ideal|acceptable|adequate|most accommodating|most forgiving|best[ _-]?practice)\b','--','references/bpc'],capture_output=True,text=True).stdout
hits=[l for l in out.splitlines()]
un=[]
for l in hits:
    f,n,t=l.split(':',2)
    if (f,int(n)) not in fl: un.append((f,n,t))
print(len(hits),len(un))
for f,n,t in un[:400]:
    if re.search(r'consensus|code minimum|floor|acceptable|adequate',t,re.I) and 'ALL-' not in f:
        print(f.replace('references/bpc/',''),n,t[:200])
EOF

